document.addEventListener("DOMContentLoaded",(function(){const toggleBtn=document.getElementById("theme-toggle"),savedTheme=localStorage.getItem("theme");savedTheme&&document.body.setAttribute("data-theme",savedTheme),toggleBtn.addEventListener("click",()=>{const currentTheme=document.body.getAttribute("data-theme"),newTheme="dark"===currentTheme?"light":"dark";document.body.setAttribute("data-theme",newTheme),localStorage.setItem("theme",newTheme)})}));